import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'

def task_func(directory):
    if not os.path.isdir(BACKUP_DIR):
        return f"Backup directory {BACKUP_DIR} does not exist. Cannot rollback update."

    if not isinstance(directory, str) or not directory:
        return "Invalid directory path. Cannot rollback update."

    backup_path = os.path.join(BACKUP_DIR, os.path.basename(os.path.normpath(directory)))
    if not os.path.isdir(backup_path):
        return f"Backup for {directory} does not exist. Cannot rollback update."

    try:
        if os.path.exists(directory):
            if os.path.isdir(directory):
                shutil.rmtree(directory)
            else:
                os.remove(directory)

        shutil.copytree(backup_path, directory)
        return directory
    except Exception as exc:
        return f"Failed to rollback update for {directory}: {exc}"

